'use strict';
const KEY='stinc-os-demo-v1';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',flag:'<path d="M5 21V4m0 0c5-4 9 4 15 0v11c-6 4-10-4-15 0"/>',play:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 8 6 4-6 4z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',bag:'<path d="M4 7h16l1 14H3zM8 8V6a4 4 0 0 1 8 0v2"/>',money:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M5 12h1m12 0h1"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-8z"/>',link:'<path d="m10 13 4-4m-6 6-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 5 0m2 2 3-3a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-5 0"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',bell:'<path d="M5 16h14l-2-4V8a5 5 0 0 0-10 0v4zm5 4h4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 13H2v7h5v-7zm16 0h2v7h-5v-7z"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3zm7 0 1 2 2 1-2 1-1 2-1-2-2-1 2-1z"/>'};
const ic=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=()=>({artist:'ralfy',campaigns:[{id:'c1',artist:'ralfy',name:'The next chapter',type:'Release rollout',date:'2026-11-20',goal:'Grow streams and capture first-party fans',status:'Active',progress:64},{id:'c2',artist:'ralfy',name:'From live to everywhere',type:'Livestream growth',date:'2026-11-13',goal:'Turn one livestream into a week of content',status:'Active',progress:38},{id:'c3',artist:'ralfy',name:'Built for the team',type:'Merchandise drop',date:'2026-11-27',goal:'Connect engaged fans with the official store',status:'Draft',progress:15},{id:'c4',artist:'roster',name:'Roster discovery sessions',type:'Livestream growth',date:'2026-11-21',goal:'Introduce emerging artists to new fans',status:'Draft',progress:10}],clips:[{id:'v1',artist:'ralfy',title:'The story behind the record',caption:'Every record starts with a real story. Which track takes you back?',hook:'Every record has a story.',duration:'0:32',score:94,platform:'YouTube Shorts',status:'Needs review',date:'2026-11-08',time:'18:00',source:'Studio session · sample source',start:'02:14'},{id:'v2',artist:'ralfy',title:'A moment for the day ones',caption:'Day ones know. Tap in with the team.',hook:'For the ones who stayed.',duration:'0:24',score:91,platform:'Instagram Reels',status:'Scheduled',date:'2026-11-09',time:'16:30',source:'Community live · sample source',start:'12:08'},{id:'v3',artist:'ralfy',title:'Studio to the streets',caption:'From the studio to your speakers. Follow for the next chapter.',hook:'The next chapter starts here.',duration:'0:41',score:88,platform:'TikTok',status:'Needs review',date:'2026-11-10',time:'19:00',source:'Studio session · sample source',start:'08:42'}],leads:[{id:'o1',name:'Independent streetwear partner',type:'Brands & partnerships',category:'Fashion · capsule collaboration',score:96,stage:'Qualified',value:'$8,000–$15,000',reason:'A capsule drop connects the artist’s independent identity with an audience already interested in STINC TEAM merchandise.',contact:'Decision-maker research required'},{id:'o2',name:'Creator audio partner',type:'Brands & partnerships',category:'Audio · livestream sponsorship',score:92,stage:'Qualified',value:'$4,000–$7,500',reason:'A recurring studio livestream creates natural product placement and repeat visibility for an audio brand.',contact:'Public partnerships contact required'},{id:'o3',name:'West Coast culture publication',type:'PR & press',category:'Editorial · artist profile',score:95,stage:'Qualified',value:'Earned coverage',reason:'An editorial profile can connect the artist’s independent career, creative process and community with a culturally relevant readership.',contact:'Editorial contact research required'},{id:'o4',name:'Independent music podcast',type:'PR & press',category:'Interview · release conversation',score:89,stage:'Draft ready',value:'Earned coverage',reason:'A long-form interview can support the release story and provide additional short-form content.',contact:'Producer contact research required'}],activity:[{title:'Content agent prepared 3 clip candidates',detail:'Studio session → short-form review queue',at:'12 minutes ago'},{title:'Partnership agent ranked 2 brand opportunities',detail:'Fit scores and pitch angles ready for review',at:'38 minutes ago'},{title:'Campaign agent mapped the next release',detail:'Content, fan capture and merchandise milestones',at:'1 hour ago'}],paused:[],settings:{weekly:true,review:true},pitches:{}});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed();if(!Array.isArray(state.campaigns)||!Array.isArray(state.clips)||!state.settings)state=seed()}catch{state=seed()}
let page=location.hash.slice(1)||'overview',filter='All',opTab='Brands & partnerships',period='30',toastTimer,lastFocus,pendingCampaign;
state.leads.forEach(x=>{if(!x.artist)x.artist='ralfy'});state.fanPages=state.fanPages||{};if(state.fanPage){state.fanPages.ralfy=state.fanPage;delete state.fanPage}
const artistName=()=>state.artist==='ralfy'?'Ralfy the Plug':'Emerging artist · demo';
const own=(arr)=>arr.filter(x=>x.artist===state.artist);
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage is unavailable. Export your workspace to keep changes.')}};
function log(title,detail){state.activity.unshift({title,detail,at:'Just now'});state.activity=state.activity.slice(0,25);save()}
const navs=[['overview','grid','Overview'],['campaigns','flag','Campaigns'],['content','play','Content studio'],['calendar','calendar','Calendar'],['opportunities','target','Opportunities'],['fans','people','Fans & community'],['commerce','bag','Commerce'],['revenue','money','Revenue']];
function shell(){document.getElementById('app').innerHTML=`<aside class="sidebar" id="sidebar"><button class="icon-btn mobile-close" data-action="menu" aria-label="Close navigation">${ic('close')}</button><a class="logo" href="#overview"><img src="assets/mark.svg" alt=""><span>STINC <span>OS</span></span></a><div class="label-tag"><strong>STINC TEAM ${ic('chevron')}</strong><small>Label workspace · Demo</small></div><div class="nav-title">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navs.map(([id,icon,name])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${ic(icon)}${name}${id==='opportunities'?`<span class="count">${own(state.leads).length}</span>`:''}</a>`).join('')}</nav><div class="nav-divider"></div><div class="nav"><a href="#roster" class="${page==='roster'?'active':''}">${ic('people')}Artist roster</a><a href="#agents" class="${page==='agents'?'active':''}">${ic('spark')}Agent workforce</a><a href="#integrations" class="${page==='integrations'?'active':''}">${ic('link')}Connections</a></div><div class="sidebar-bottom"><div class="agent-mini"><span class="dot"></span><strong class="small">Your team, in motion</strong><p class="muted small" style="margin-top:5px">${4-state.paused.length} demo agents enabled</p><a href="#agents" class="btn subtle small">Manage workforce ${ic('arrow')}</a></div><div class="user"><div class="avatar">EV</div><div><strong>EVOL</strong><small>Label manager · Demo persona</small></div><button class="icon-btn" data-action="settings" aria-label="Workspace settings" style="margin-left:auto">${ic('grid')}</button></div></div></aside><button class="nav-scrim" data-action="menu" aria-label="Close navigation overlay" tabindex="-1"></button><div class="shell"><header class="topbar"><div class="breadcrumbs"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-controls="sidebar" aria-expanded="false">${ic('menu')}</button><span class="crumb-label">Workspace</span><span class="crumb-label">/</span><strong>${esc(artistName())}</strong></div><div class="top-right"><span class="badge"><span class="dot"></span>Demo workspace</span><select class="artist-select" id="artist-select" aria-label="Select artist"><option value="ralfy" ${state.artist==='ralfy'?'selected':''}>Ralfy the Plug</option><option value="roster" ${state.artist==='roster'?'selected':''}>Emerging artist · demo</option></select><button class="icon-btn" data-action="notifications" aria-label="Activity notifications">${ic('bell')}</button></div></header><main class="main skeleton" id="main" tabindex="-1">${renderPage()}</main></div>`;bind();}
const button=(label,action,primary=false,icon='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${icon?ic(icon):''}${label}</button>`;
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
const footer=()=>`<footer class="footer"><span>STINC OS / Independent ambition. Connected execution.</span><button data-action="about">Concept demo · Sample data · No accounts connected ${ic('arrow')}</button></footer>`;
function metrics(items){return `<div class="metrics">${items.map(([label,num,trend,icon])=>`<div class="metric"><div class="metric-label">${ic(icon||'grid')}${label}</div><div class="number">${num}</div><div class="trend">↗ ${trend}<span>vs. previous period</span></div><svg class="spark" viewBox="0 0 70 30" fill="none" aria-hidden="true"><path d="M0 26 9 20 17 23 25 12 34 17 44 9 52 12 60 3 70 0" stroke="#a6d265" stroke-width="1.6"/></svg></div>`).join('')}</div>`}
function chart(){return `<div class="chart"><svg viewBox="0 0 530 156" role="img" aria-label="Sample content views trend upward during the selected period"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#c5f277" stop-opacity=".16"/><stop offset="1" stop-color="#c5f277" stop-opacity="0"/></linearGradient></defs>${[20,60,100,140].map((y,i)=>`<path d="M35 ${y}H525" stroke="#30362e" stroke-dasharray="3 5"/><text x="0" y="${y+4}" fill="#7c8873" font-size="9">${[60,40,20,0][i]}k</text>`).join('')}<path d="M35 125 60 119 85 124 110 106 135 113 160 97 185 105 210 80 235 85 260 68 285 82 310 59 335 66 360 43 385 54 410 32 435 45 460 20 485 28 525 9V145H35Z" fill="url(#area)"/><path d="M35 125 60 119 85 124 110 106 135 113 160 97 185 105 210 80 235 85 260 68 285 82 310 59 335 66 360 43 385 54 410 32 435 45 460 20 485 28 525 9" fill="none" stroke="#c5f277" stroke-width="2" stroke-linejoin="round"/><path d="M35 137 70 133 105 137 140 123 175 128 210 115 245 124 280 108 315 119 350 103 385 111 420 93 455 105 490 88 525 94" fill="none" stroke="#799eae" stroke-width="1.5"/></svg><div class="chart-labels">${(period==='7'?['Nov 1','Nov 2','Nov 3','Nov 4','Nov 5','Nov 7']:['Oct 9','Oct 15','Oct 21','Oct 27','Nov 2','Nov 7']).map(t=>`<span>${t}</span>`).join('')}</div></div>`}
function overview(){let alt=state.artist!=='ralfy';return heading('Make your next move.',`${artistName()} · Your artist business, connected.`,button('Export report','export',false,'download')+button('New campaign','new-campaign',true,'plus'))+`<section class="hero"><div class="hero-copy"><div class="eyebrow green">THE INDEPENDENT ADVANTAGE</div><h2>Independent moves.<br>Major-label execution.</h2><p>One artist. An entire workforce. Turn your next release into a connected growth campaign.</p>${button('Build a campaign','new-campaign',true,'spark')} <button class="btn subtle" data-action="tour" style="margin-left:12px">Take a tour ${ic('arrow')}</button></div>${alt?'<div class="hero-image" style="display:grid;place-items:center"><span style="font-family:Space Grotesk;font-size:100px;color:#c5f27733">EA</span></div><div class="hero-label">DEMO ROSTER SLOT<b>EMERGING ARTIST</b></div>':'<div class="hero-image"><img src="assets/ralfy.png" alt="Ralfy the Plug, from the official STINC TEAM artist profile"></div><div class="hero-label">ARTIST SPOTLIGHT<b>RALFY THE PLUG</b></div>'}</section><div class="split" style="margin-bottom:10px"><span class="eyebrow muted">MOMENTUM / SAMPLE PERFORMANCE</span><select class="artist-select" id="period" aria-label="Performance date range"><option value="30" ${period==='30'?'selected':''}>Last 30 days</option><option value="7" ${period==='7'?'selected':''}>Last 7 days</option></select></div>`+metrics(alt?[['Content views','42.8K','12.4%','play'],['Music streams','18.2K','9.2%','headphones'],['Owned fans','284','8.1%','people'],['Attributed sales','$840','11.3%','bag']]:period==='7'?[['Content views','324.8K','21.6%','play'],['Music streams','84.2K','10.4%','headphones'],['Owned fans','1,862','4.2%','people'],['Attributed sales','$3,420','18.1%','bag']]:[['Content views','1.28M','24.8%','play'],['Music streams','342.8K','18.2%','headphones'],['Owned fans','1,862','12.6%','people'],['Attributed sales','$12,480','32.4%','bag']])+`<div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>Attention into momentum</h2><p>Sample cross-platform content performance</p></div><div class="legend"><span><i></i>Current</span><span><i class="second"></i>Previous</span></div></div><div class="chart-summary"><b>${alt?'42.8K':period==='7'?'324.8K':'1,284,650'}</b><span>↗ ${period==='7'?'21.6':'24.8'}%</span></div>${chart()}</section><section class="panel"><div class="panel-head"><div><h2>Your next best moves</h2><p>High-impact actions, ready for you.</p></div><span class="badge purple">${ic('spark')}Agent picks</span></div><div class="task-row"><div class="task-icon">${ic('play')}</div><div><h3>Turn one session into a week of content</h3><p>Review clip candidates and build your queue.</p></div>${button('Review','go-content')}</div><div class="task-row"><div class="task-icon">${ic('target')}</div><div><h3>Open the right brand conversations</h3><p>2 sample opportunities match your audience.</p></div>${button('Explore','go-opportunities')}</div><div class="task-row"><div class="task-icon">${ic('flag')}</div><div><h3>Give the next release a full rollout</h3><p>Connect content, fans and your storefront.</p></div>${button('Plan','new-campaign')}</div></section></div><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>Campaigns in motion</h2><a class="btn subtle" href="#campaigns">View all ${ic('arrow')}</a></div>${own(state.campaigns).slice(0,3).map(c=>`<div class="campaign-row"><div class="art-tile">${c.id==='c1'?'<img src="assets/ralfy.png" alt="">':ic(c.type.includes('Merch')?'bag':'play')}</div><div><h3>${esc(c.name)}</h3><p>${esc(c.type)} · ${fmtDate(c.date)}</p></div><div class="row-end"><button class="badge ${c.status==='Draft'?'gray':''}" data-action="campaign:${c.id}">${esc(c.status)} ${ic('chevron')}</button><div class="progress" aria-label="${c.progress}% complete"><span style="width:${c.progress}%"></span></div></div></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Behind the scenes</h2><a href="#agents" class="btn subtle">Agent activity ${ic('arrow')}</a></div>${state.activity.slice(0,3).map(a=>`<div class="activity"><span class="activity-dot"></span><div><b>${esc(a.title)}</b><p>${esc(a.detail)} · ${esc(a.at)}</p></div></div>`).join('')}</section></div>`+footer()}
function campaigns(){let rows=own(state.campaigns).filter(c=>filter==='All'||c.status===filter);return heading('Campaigns','A coordinated plan for every next chapter.',button('New campaign','new-campaign',true,'plus'))+tabs(['All','Active','Draft','Completed'])+(rows.length?`<div class="cards">${rows.map(c=>`<article class="panel campaign-card"><div class="art-tile">${c.id==='c1'?'<img src="assets/ralfy.png" alt="Ralfy the Plug">':ic(c.type.includes('Merch')?'bag':c.type.includes('Live')?'play':'flag')}</div><span class="badge ${c.status==='Draft'?'gray':''}">${esc(c.status)}</span><h2>${esc(c.name)}</h2><p>${esc(c.goal)}</p><div class="split small"><span class="muted">${esc(c.type)}</span><span>${c.progress}%</span></div><div class="progress"><span style="width:${c.progress}%"></span></div><div class="split small muted" style="margin-bottom:17px"><span>Target date</span><span>${fmtDate(c.date)}</span></div>${button('Open campaign',`campaign:${c.id}`,false,'arrow')}</article>`).join('')}</div>`:empty('No campaigns here yet.','Build a plan around a release, livestream or merchandise drop.','Create campaign','new-campaign'))+footer()}
function tabs(list){return `<div class="tabs" role="group" aria-label="Filter results">${list.map(t=>`<button class="tab ${filter===t?'active':''}" data-filter="${esc(t)}" aria-pressed="${filter===t}">${t}</button>`).join('')}</div>`}
function content(){let rows=own(state.clips).filter(c=>filter==='All'||c.status===filter);return heading('Content studio','One long-form moment. A week of possibilities.',button('Add source','add-source',true,'plus'))+`<div class="note">Demo production workspace. Clip candidates illustrate a clipping integration; no video is processed or published from this demo.</div>`+tabs(['All','Needs review','Scheduled'])+(rows.length?`<div class="content-grid">${rows.map(c=>`<article class="panel clip"><div class="clip-art"><img src="assets/ralfy.png" alt="Artist image used for sample clip storyboard"><div class="play">${ic('play')}</div><div class="caption">${esc(c.hook)}</div><span class="duration">${c.duration}</span></div><div class="split"><span class="badge ${c.status==='Scheduled'?'':'yellow'}">${esc(c.status)}</span><span class="small green">${c.score} / 100 fit</span></div><h3>${esc(c.title)}</h3><p>${esc(c.platform)} · 9:16 · ${esc(c.duration)}</p><div class="split"><span class="muted small">${esc(c.source)}</span>${button(c.status==='Scheduled'?'Edit':'Review',`clip:${c.id}`,false,'arrow')}</div></article>`).join('')}</div>`:empty('Your next moment starts here.','Add a sample source to explore a complete clipping workflow.','Add source','add-source'))+footer()}
function calendar(){let clips=own(state.clips).filter(c=>c.status==='Scheduled').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return heading('Publishing calendar','A clear view of what is going out, and when.',button('Schedule content','go-content',true,'plus'))+`<div class="note">All times shown in America/Los_Angeles. Scheduled items are saved demo plans; connect authorized platform accounts for live publishing.</div>`+(clips.length?`<div class="calendar-list">${clips.map(c=>`<div class="calendar-day"><div class="day-label">${new Date(c.date+'T12:00').toLocaleDateString('en-US',{month:'short'})}<b>${Number(c.date.slice(-2))}</b></div><article class="panel calendar-event"><span class="task-icon">${ic('play')}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.platform)} · ${esc(c.time)} PT</p></div><span class="badge">Scheduled in demo</span>${button('Edit',`clip:${c.id}`)}</article></div>`).join('')}</div>`:empty('A clear calendar, ready to fill.','Review a clip, pick a platform and schedule its next appearance.','Open content studio','go-content'))+footer()}
function opportunities(){let rows=own(state.leads).filter(x=>x.type===opTab);return heading('Opportunity engine','The right conversations. A new lane of revenue.',button('Add opportunity','new-lead',true,'plus'))+`<div class="tabs" role="group" aria-label="Opportunity category">${['Brands & partnerships','PR & press'].map(t=>`<button class="tab ${opTab===t?'active':''}" data-optab="${esc(t)}" aria-pressed="${opTab===t}">${t}</button>`).join('')}</div><div class="note">Illustrative prospects and fit scores. These are opportunity archetypes, not verified leads or promised deals. Public contact research and manager approval precede outreach.</div><section class="panel"><div class="panel-head"><div><h2>${opTab==='PR & press'?'Build the story. Earn the conversation.':'Partners worth building with.'}</h2><p>${rows.length} opportunities · ${esc(artistName())}</p></div><span class="badge purple">Fit-ranked</span></div><div class="table-wrap"><table><thead><tr><th>Opportunity</th><th>Fit score</th><th>Potential / format</th><th>Stage</th><th>Next move</th></tr></thead><tbody>${rows.map(o=>`<tr><td>${esc(o.name)}<small>${esc(o.category)}</small></td><td><span class="score">${o.score||'—'}</span><small>${o.score?'Sample fit':'Not scored'}</small></td><td>${esc(o.value)}</td><td><span class="badge ${o.stage==='Qualified'?'':'purple'}">${esc(o.stage)}</span></td><td>${button('Review & pitch',`lead:${o.id}`)}</td></tr>`).join('')}</tbody></table></div></section>`+footer()}
function fans(){let alt=state.artist!=='ralfy';return heading('Fans, not just followers.','Build an audience you can reach again.',button('Create fan capture','fan-form',true,'plus'))+metrics([['Owned fans',alt?'284':'1,862','12.6%','people'],['Email opt-ins',alt?'210':'1,420','15.2%','link'],['SMS opt-ins',alt?'74':'442','8.1%','bell'],['Engaged this month',alt?'182':'1,248','18.3%','target']])+`<div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>Your community, closer</h2><p>Sample segments · Aggregate data only</p></div></div>${[['Day ones','Repeat engagement across three or more campaigns','428'],['Release ready','Opted in to music and release announcements','986'],['Merch insiders','Interested in drops and store updates','448']].map(([n,d,v])=>`<div class="segment"><div class="task-icon">${ic('people')}</div><div><h3>${n}</h3><p>${d}</p></div><span class="number">${alt?Math.round(Number(v.replace(',',''))*.15):v}</span></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Give fans a reason to stay.</h2></div><div class="panel-body"><p class="muted small" style="margin-bottom:20px">Put a clear fan-capture moment behind every campaign: early music access, a livestream reminder or the next drop.</p><div class="step"><h3>01 / Invite</h3><p class="muted small">A link in the content they already love.</p></div><br><div class="step"><h3>02 / Connect</h3><p class="muted small">Explicit email or SMS consent.</p></div><br><div class="step"><h3>03 / Bring them back</h3><p class="muted small">Relevant updates around the next moment.</p></div><br>${button('Build a capture page','fan-form',true,'arrow')}</div></section></div>`+footer()}
function commerce(){return heading('Culture into commerce.','Connect the attention to something fans can own.',button('Plan a drop','merch-plan',true,'plus'))+`<section class="panel merch-feature"><img src="assets/merch.jpg" alt="Long Live the Ruler shirt from the official STINC TEAM store"><div class="merch-info"><span class="eyebrow green">OFFICIAL STORE / PRODUCT SPOTLIGHT</span><h2>Built for the team.</h2><p>Bring merchandise into the rollout. Coordinate the content, the early-access list and the drop from the same workspace.</p><div class="split small" style="margin-bottom:24px"><span class="badge gray">Shopify · Not connected</span><span class="muted">Public product image</span></div><div class="actions">${button('Build a drop campaign','merch-plan',true,'bag')}<a class="btn" href="https://stincteamtgf.com/" target="_blank" rel="noopener noreferrer">Visit official store ↗</a></div></div></section><br>`+metrics([['Sample sales','$12,480','32.4%','bag'],['Sample orders','208','21.2%','grid'],['Average order','$60.00','9.2%','money'],['Store conversion','3.4%','0.8 pts','target']])+`<div class="note">Store metrics are illustrative. Product sales, inventory and checkout remain in Shopify. A conversational storefront designer is part of the future product roadmap.</div>`+footer()}
function revenue(){return heading('Know what is coming in.','A view across your artist business, with the gaps visible.',button('Export report','export',false,'download'))+`<div class="note">Financial demonstration only. No distributor, royalty, publishing or bank accounts are connected. Amounts below are sample records, not actual earnings or an audit of amounts owed.</div>`+metrics([['Reported · sample','$18,720','16.2%','money'],['Estimated · sample','$4,860','8.4%','headphones'],['Awaiting review','$2,140','5.1%','calendar'],['Revenue sources','4','1 source','link']])+`<section class="panel"><div class="panel-head"><div><h2>Revenue ledger</h2><p>Sample reporting period · October 2026 · USD</p></div><a class="btn" href="#integrations">Manage connections ${ic('arrow')}</a></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Amount</th><th>Record type</th><th>What happens next</th></tr></thead><tbody>${[['Merchandise','$12,480','Reported','Reconcile with Shopify orders'],['Distribution','$6,240','Reported','Match distributor statement'],['Streaming forecast','$4,860','Estimated','Await final statement'],['Publishing','$2,140','Awaiting review','Confirm registrations and reporting period']].map(([s,a,t,n])=>`<tr><td>${s}<small>Illustrative record</small></td><td>${a}</td><td><span class="badge ${t==='Reported'?'':t==='Estimated'?'purple':'yellow'}">${t}</span></td><td>${n}</td></tr>`).join('')}</tbody></table></div></section>`+footer()}
const agents=[['campaign','Campaign strategist','Turns an artist goal into a coordinated release, content and fan-growth plan.','flag'],['content','Content producer','Organizes clip candidates, captions and the publishing queue.','play'],['partnership','Opportunity scout','Ranks commercial and editorial opportunities with a visible reason for fit.','target'],['community','Community operator','Plans fan capture and relevant follow-up around releases and drops.','people']];
function workforce(){return heading('Your independent workforce.','A visible team behind every move.',button('Execution controls','settings',false,'grid'))+`<div class="note">Agent activity is simulated in this demo. Run a planning task to create a saved review item. External publishing and outreach are disabled until authorized integrations are implemented.</div><div class="cards">${agents.map(([id,n,d,i])=>`<article class="panel agent-card"><div class="split"><div class="agent-orb">${ic(i)}</div><span class="badge ${state.paused.includes(id)?'gray':'purple'}">${state.paused.includes(id)?'Paused':'Demo enabled'}</span></div><h2>${n}</h2><p>${d}</p>${button(state.paused.includes(id)?'Resume agent':'Pause agent',`toggle-agent:${id}`)}${!state.paused.includes(id)?button('Run planning task',`run-agent:${id}`,true,'spark'):''}</article>`).join('')}</div><br><section class="panel"><div class="panel-head"><h2>Execution history</h2><span class="badge gray">Saved locally</span></div>${state.activity.map(a=>`<div class="activity"><span class="activity-dot"></span><div><b>${esc(a.title)}</b><p>${esc(a.detail)} · ${esc(a.at)}</p></div></div>`).join('')}</section>`+footer()}
function roster(){return heading('A roster. One command center.','Artist-specific campaigns, with label-wide visibility.',button('How this demo works','about',false,'grid'))+`<div class="calendar-list">${[['ralfy','Ralfy the Plug','Featured artist · STINC TEAM'],['roster','Emerging artist','Sample roster slot · Not a real artist']].map(([id,n,d])=>`<article class="panel roster-card">${id==='ralfy'?'<img src="assets/ralfy.png" alt="Ralfy the Plug">':'<div class="roster-avatar">EA</div>'}<div><span class="eyebrow muted">${id==='ralfy'?'ARTIST SPOTLIGHT':'DEMO ROSTER SLOT'}</span><h2>${n}</h2><p class="muted small">${d}</p><p class="small green" style="margin-top:8px">${state.campaigns.filter(c=>c.artist===id).length} campaigns · ${state.clips.filter(c=>c.artist===id).length} content assets</p></div>${button('Open workspace',`artist:${id}`,id===state.artist,'arrow')}</article>`).join('')}</div>`+footer()}
function integrations(){return heading('Connect your ecosystem.','Bring your tools together, with clear permissions.')+`<div class="note">This free public demo does not collect passwords, API keys or account credentials. Connection details show the planned integration scope and requirements.</div><section class="panel">${[['YouTube','Video analytics, long-form sources and Shorts publishing','Y'],['Twitch','Livestream sources and audience context','T'],['Kick','Livestream sources and content planning','K'],['Instagram & Facebook','Professional account analytics and approved publishing','◎'],['TikTok','Video publishing and content analytics','♪'],['Shopify','Products, orders and storefront conversion','S'],['Clipping provider','Clip generation, reframing and caption exports','C'],['Fan CRM','Consented fan capture and segmentation','F'],['Distributor & publishing','Statements, reporting periods and reconciliation','D']].map(([n,d,i])=>`<div class="settings-row"><div class="connection-logo">${i}</div><div class="info"><h3>${n}</h3><p>${d}</p></div><span class="badge gray">Not connected</span>${button('Details',`connect:${n}`)}</div>`).join('')}</section>`+footer()}
function renderPage(){const views={overview,campaigns,content,calendar,opportunities,fans,commerce,revenue,agents:workforce,roster,integrations};return (views[page]||overview)()}
function empty(t,d,b,a){return `<div class="empty"><h2>${t}</h2><p>${d}</p>${button(b,a,true,'plus')}</div>`}
function fmtDate(d){return new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}
function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
function navigate(p){if(location.hash==='#'+p){page=p;shell()}else location.hash=p}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;shell()}));document.querySelectorAll('[data-optab]').forEach(b=>b.addEventListener('click',()=>{opTab=b.dataset.optab;shell()}));document.getElementById('artist-select').addEventListener('change',e=>{state.artist=e.target.value;save();filter='All';shell()});document.getElementById('period')?.addEventListener('change',e=>{period=e.target.value;shell()})}
function modal(title,body,wide=false){lastFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${ic('close')}</button></header><div class="modal-content">${body}</div></section></div>`;document.body.style.overflow='hidden';document.querySelectorAll('#overlay [data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));document.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});document.querySelector('.modal input,.modal select,.modal textarea,.modal button')?.focus()}
function closeModal(){document.getElementById('overlay').innerHTML='';document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus()}
const field=(label,name,value='',type='text',hint='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" required ${type==='date'?'min="2026-11-07"':''}>${hint?`<span class="hint">${hint}</span>`:''}</label>`;
function newCampaign(type='Release rollout'){modal('Make the next move.',`<p>Start with the goal. Build a connected plan around it.</p><form id="campaign-form">${field('Campaign name','name','','text')}<div class="form-grid"><label class="field">Campaign type<select name="type">${['Release rollout','Livestream growth','Merchandise drop','Brand partnerships','PR campaign','Always-on growth'].map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select></label>${field('Target date','date','2026-11-20','date')}</div><label class="field">What are we working toward?<textarea name="goal" required placeholder="Grow the next release through livestreams, daily clips and a fan early-access list."></textarea></label><div class="note">This creates a saved campaign plan for ${esc(artistName())}. You can review the rollout before activation.</div><div class="modal-footer">${button('Cancel','close')}<button class="btn primary" type="submit">Build campaign ${ic('arrow')}</button></div></form>`);document.getElementById('campaign-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const c={id:'c'+Date.now(),artist:state.artist,name:f.get('name').trim(),type:f.get('type'),date:f.get('date'),goal:f.get('goal').trim(),status:'Draft',progress:0};if(!c.name||!c.goal)return;state.campaigns.unshift(c);log('Campaign strategist built “'+c.name+'”','A coordinated draft is ready for manager review.');closeModal();page='campaigns';filter='All';if(location.hash==='#campaigns'){shell();campaignDetail(c.id)}else{pendingCampaign=c.id;navigate('campaigns')}})}
const campaignPlans={
'Release rollout':[['Set the release story','Confirm the release assets, audience, DSP destination and one primary streaming goal.'],['Build the anticipation','Plan a studio livestream, three teaser clips and a consent-based early-access fan list.'],['Coordinate release day','Align the music link, release-day posts, community announcement and merchandise spotlight.'],['Extend the momentum','Review the first-week response, repurpose standout moments and plan the follow-up content.']],
'Livestream growth':[['Give the session a purpose','Choose the platform, format and fan action; set a live audience and watch-time target.'],['Bring fans into the room','Plan the announcement, reminder clips and opt-in livestream notification.'],['Make the live moment count','Outline the opening hook, audience interaction and approved sponsor or merchandise moments.'],['Turn live into lasting reach','Review the recording for clips, schedule platform-specific posts and invite viewers back.']],
'Merchandise drop':[['Build the drop','Confirm product, inventory, pricing, store destination and sales target with the team.'],['Give insiders the first look','Plan the product reveal, early-access fan segment and creative assets.'],['Launch across the ecosystem','Coordinate the store release, livestream mention and approved launch posts.'],['Learn and bring fans back','Review sales and conversion, follow up with consented fans and reconcile store orders.']],
'Brand partnerships':[['Define the offer','Set the audience story, available deliverables, partner categories and target deal size.'],['Qualify the right partners','Research public brand information, document fit and verify business contact sources.'],['Prepare the conversation','Build a tailored pitch and evidence-backed offer for manager review.'],['Manage the relationship','Track approved follow-ups, negotiate scope and record deliverables and outcomes.']],
'PR campaign':[['Find the story','Define the editorial angle, release context and verified facts for the press kit.'],['Build the media list','Research relevant publications, podcasts and publicly listed editorial contacts.'],['Pitch with a purpose','Prepare a short, tailored story proposal and manager-approved press assets.'],['Coordinate the coverage','Track responses, interview preparation, approved follow-ups and published links.']],
'Always-on growth':[['Choose the growth focus','Set a measurable audience or business goal and document the current baseline.'],['Build the weekly rhythm','Plan long-form sessions, daily short-form moments and a recurring fan invitation.'],['Connect the business','Coordinate community, commerce and relevant commercial opportunities.'],['Review and improve','Compare performance with the baseline and adjust next week’s plan.']]};
function campaignDetail(id){let c=state.campaigns.find(c=>c.id===id);if(!c)return;modal(esc(c.name),`<div class="split" style="margin-bottom:18px"><span class="badge ${c.status==='Draft'?'gray':''}">${esc(c.status)}</span><span class="muted small">${esc(c.type)} · ${fmtDate(c.date)}</span></div><p>${esc(c.goal)}</p>${(campaignPlans[c.type]||campaignPlans['Always-on growth']).map(([t,d],i)=>`<div class="step"><div class="step-number">${i+1}</div><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}<div class="note">Activation updates your demo plan. External posting, outreach and DSP actions require authorized integrations.</div><div class="modal-footer">${button('Open content','campaign-content')} ${c.status==='Draft'?button('Activate demo plan',`activate:${id}`,true,'check'):c.status==='Active'?button('Mark complete',`complete:${id}`,true,'check'):button('Close','close')}</div>`)}
function clipDetail(id){let c=state.clips.find(c=>c.id===id);if(!c)return;modal('Review the moment.',`<p>${esc(c.title)} · Storyboard and publishing plan</p><div class="note">Sample visual storyboard. No playable source video is attached. Candidate: ${esc(c.start)} · ${esc(c.duration)} · Fit score ${c.score}/100.</div><form id="clip-form"><label class="field">On-screen hook<input name="hook" value="${esc(c.hook)}" required maxlength="100"></label><label class="field">Caption<textarea name="caption" required>${esc(c.caption)}</textarea></label><label class="field">Destination<select name="platform">${['YouTube Shorts','Instagram Reels','TikTok','Facebook Reels'].map(t=>`<option ${c.platform===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="form-grid">${field('Publish date (PT)','date',c.date,'date')}${field('Publish time (PT)','time',c.time,'time')}</div><div class="modal-footer">${c.status==='Scheduled'?button('Move to review',`unschedule:${id}`):button('Cancel','close')}<button class="btn primary" type="submit">Save to demo calendar ${ic('calendar')}</button></div></form>`);document.getElementById('clip-form').addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);Object.assign(c,{hook:f.get('hook').trim(),caption:f.get('caption').trim(),platform:f.get('platform'),date:f.get('date'),time:f.get('time'),status:'Scheduled'});log('Content scheduled: '+c.title,c.platform+' · '+fmtDate(c.date)+' · '+c.time+' PT · Demo plan only');closeModal();shell();toast('Saved to your demo calendar. No live post was sent.')})}
function addSource(){modal('One source. More possibilities.',`<p>Add a source reference to create three sample clip candidates for review.</p><form id="source-form">${field('Source title','title','','text')}<label class="field">Source URL<input name="url" type="url" placeholder="https://www.youtube.com/watch?v=…" required><span class="hint">A reference only. This demo does not fetch or process the video.</span></label><label class="field">Source type<select name="type"><option>YouTube video</option><option>Twitch livestream</option><option>Kick livestream</option><option>Studio session</option></select></label><div class="modal-footer">${button('Cancel','close')}<button type="submit" class="btn primary">Create sample candidates ${ic('spark')}</button></div></form>`);document.getElementById('source-form').addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),title=f.get('title').trim();if(!title)return;let url=new URL(f.get('url'));if(!['https:','http:'].includes(url.protocol)){toast('Use an https:// or http:// source URL.');return}['The opening hook','The story worth sharing','The community moment'].forEach((t,i)=>state.clips.push({id:'v'+Date.now()+i,artist:state.artist,title:t,caption:'Tap in for the next chapter. Follow '+artistName()+' for more.',hook:t,duration:['0:24','0:32','0:41'][i],score:92-i*3,platform:['YouTube Shorts','Instagram Reels','TikTok'][i],status:'Needs review',date:'2026-11-12',time:'18:00',source:title+' · sample candidate',start:['00:20','02:14','05:08'][i],url:url.href}));log('Content producer prepared 3 sample candidates',title+' · Source reference saved; video processing not connected.');closeModal();filter='All';navigate('content');shell();toast('Three sample storyboards are ready for review.')})}
function leadDetail(id){let o=state.leads.find(x=>x.id===id);modal('A conversation worth starting.',`<span class="badge purple" style="margin-bottom:18px">${esc(o.type)} · ${o.score}/100 sample fit</span><h3 style="margin-bottom:10px">${esc(o.name)}</h3><p>${esc(o.reason)}</p><div class="detail-list"><div><span>Potential / format</span><b>${esc(o.value)}</b></div><div><span>Contact status</span><b>${esc(o.contact)}</b></div><div><span>Pipeline stage</span><b>${esc(o.stage)}</b></div></div><br><label class="field">Pitch draft<textarea id="pitch" style="min-height:150px">${esc(state.pitches[id]||`Hi [name],\n\nI’m reaching out on behalf of ${artistName()} and STINC TEAM. We’re exploring ${o.type==='PR & press'?'a conversation around independent music, creative process and community':'a focused partnership around music, livestream content and fan culture'}.\n\n${o.reason}\n\nWould you be open to a short conversation about the fit?\n\n[Manager name]`)}</textarea><span class="hint">Template only. Verify the recipient, artist facts, offer and permissions before sending.</span></label><div class="modal-footer">${button('Save pitch draft',`save-pitch:${id}`,true,'check')}${button('Move to manager review',`ready-lead:${id}`)}</div>`)}
function fanForm(){modal('Build a fan-capture moment.',`<p>Create a saved page brief for the next release, livestream or drop. Live fan collection requires a CRM connection.</p><form id="fan-form">${field('Page headline','headline',state.fanPages[state.artist]?.headline||'Be first for the next chapter.')}<label class="field">Offer<select name="offer">${['Early music access','Livestream reminder','Merchandise early access'].map(t=>`<option ${state.fanPages[state.artist]?.offer===t?'selected':''}>${t}</option>`).join('')}</select></label>${field('Call to action','cta',state.fanPages[state.artist]?.cta||'Join the inner circle')}<label class="check"><input type="checkbox" required>Include explicit email opt-in and an unsubscribe option.</label><div class="modal-footer">${button('Cancel','close')}<button type="submit" class="btn primary">Save page brief ${ic('check')}</button></div></form>`);document.getElementById('fan-form').addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);state.fanPages[state.artist]=Object.fromEntries(f);log('Community operator saved a fan-capture brief',f.get('headline')+' · '+f.get('offer'));closeModal();shell();toast('Fan-capture brief saved. Live collection is not connected.')})}
function newLead(){modal('Add an opportunity.',`<form id="lead-form">${field('Brand or publication','name')}<label class="field">Pipeline<select name="type"><option>Brands & partnerships</option><option>PR & press</option></select></label>${field('Category / angle','category')}<label class="field">Why does this fit?<textarea name="reason" required></textarea></label><div class="modal-footer">${button('Cancel','close')}<button class="btn primary" type="submit">Save opportunity</button></div></form>`);document.getElementById('lead-form').addEventListener('submit',e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));state.leads.push({...f,artist:state.artist,id:'o'+Date.now(),score:0,stage:'Research needed',value:'To be scoped',contact:'Public contact verification required'});opTab=f.type;log('Opportunity added: '+f.name,'Research and qualification required.');closeModal();shell();toast('Opportunity saved for research.')})}
function settings(){modal('You set the boundaries.',`<p>Demo execution preferences are saved in this browser. Live actions remain unavailable until connected.</p><form id="settings-form"><label class="check"><input type="checkbox" name="review" ${state.settings.review?'checked':''}>Require manager review in campaign plans</label><label class="check"><input type="checkbox" name="weekly" ${state.settings.weekly?'checked':''}>Include a weekly performance review in plans</label><div class="note">Live publishing: disabled<br>Live outreach: disabled<br>Payments and purchases: disabled</div><div class="modal-footer">${button('Export workspace','export')}<button class="btn primary" type="submit">Save preferences</button></div></form>`);document.getElementById('settings-form').addEventListener('submit',e=>{e.preventDefault();state.settings={review:e.target.review.checked,weekly:e.target.weekly.checked};save();closeModal();toast('Workspace preferences saved.')})}
function download(){let data={...state,exportedAt:new Date().toISOString(),notice:'STINC OS concept demo. Sample records; not actual artist analytics or financial data.'};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='stinc-os-demo-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo workspace exported as JSON.')}
function action(a){const [act,...parts]=a.split(':'),id=parts.join(':');if(act==='close')return closeModal();if(act==='menu'){let side=document.getElementById('sidebar');let open=side.classList.toggle('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded',String(open));if(open)document.querySelector('.mobile-close').focus();else document.querySelector('.mobile-menu').focus();return}if(act.startsWith('go-'))return navigate(act.slice(3));switch(act){case 'new-campaign':return newCampaign();case 'merch-plan':return newCampaign('Merchandise drop');case 'campaign':return campaignDetail(id);case 'campaign-content':closeModal();return navigate('content');case 'activate':case 'complete':{let c=state.campaigns.find(x=>x.id===id);c.status=act==='activate'?'Active':'Completed';c.progress=act==='activate'?10:100;log('Campaign '+(act==='activate'?'activated':'completed')+': '+c.name,'Demo plan updated; no external actions performed.');closeModal();shell();return toast('Campaign '+c.status.toLowerCase()+'.')}case 'clip':return clipDetail(id);case 'add-source':return addSource();case 'unschedule':{state.clips.find(x=>x.id===id).status='Needs review';save();closeModal();shell();return toast('Moved back to the review queue.')}case 'lead':return leadDetail(id);case 'new-lead':return newLead();case 'save-pitch':state.pitches[id]=document.getElementById('pitch').value;state.leads.find(x=>x.id===id).stage='Draft ready';log('Pitch draft saved','No message sent. Verify recipient and offer before live outreach.');closeModal();shell();return toast('Pitch saved. No outreach was sent.');case 'ready-lead':state.pitches[id]=document.getElementById('pitch').value;state.leads.find(x=>x.id===id).stage='Ready for review';log('Opportunity moved to manager review','Contact verification and approval required before outreach.');closeModal();shell();return toast('Saved for manager review. No outreach was sent.');case 'fan-form':return fanForm();case 'settings':return settings();case 'export':return download();case 'artist':state.artist=id;save();closeModal();return navigate('overview');case 'toggle-agent':state.paused=state.paused.includes(id)?state.paused.filter(x=>x!==id):[...state.paused,id];save();shell();return;case 'run-agent':{if(state.paused.includes(id))return;let title=agents.find(x=>x[0]===id)[1];if(id==='campaign')return newCampaign();if(id==='content')return addSource();if(id==='community')return fanForm();log(title+' refreshed the opportunity review','Two sample brand opportunities ranked; public contact research still required.');shell();return toast('Sample opportunity review added to execution history.')}case 'connect':return modal(esc(id)+' connection',`<p>This connector is part of the production implementation. It is not connected in the public demo.</p><div class="step"><div class="step-number">1</div><div><h3>Authorize an account</h3><p>Use the provider’s supported authorization flow with the minimum required permissions.</p></div></div><div class="step"><div class="step-number">2</div><div><h3>Confirm scope and availability</h3><p>Publishing, analytics and data access depend on the provider’s API capabilities, account eligibility and review requirements.</p></div></div><div class="step"><div class="step-number">3</div><div><h3>Choose execution controls</h3><p>Set review requirements, limits and logging before enabling live actions.</p></div></div><div class="modal-footer">${button('Understood','close',true)}</div>`);case 'notifications':return modal('Your team, in motion.',state.activity.slice(0,8).map(x=>`<div class="step"><span class="activity-dot"></span><div><h3>${esc(x.title)}</h3><p>${esc(x.detail)} · ${esc(x.at)}</p></div></div>`).join('')+`<div class="modal-footer">${button('Close','close')}</div>`);case 'tour':return modal('From attention to a business.',`<p>Three connected journeys to explore with EVOL and the team.</p>${[['Build the next rollout','Create a campaign, review the coordinated plan and activate it in the demo.'],['Make every session work harder','Add a video reference, create sample clip candidates and save posts to the calendar.'],['Open a new revenue lane','Review a brand or press opportunity, refine a pitch and move it into manager review.']].map(([t,d],i)=>`<div class="step"><div class="step-number">${i+1}</div><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}<div class="modal-footer">${button('Start a campaign','new-campaign',true,'arrow')}</div>`);case 'about':return modal('An operating system for independence.',`<p>STINC OS is a presentation concept prepared for a discussion with EVOL / STINC TEAM. It is not an official STINC TEAM product or endorsement.</p><ul class="help-list"><li><b>Working in this demo:</b> campaigns, clip storyboards, demo scheduling, pitch drafts, roster switching, fan-capture briefs, agent controls and JSON export.</li><li><b>Saved in your browser:</b> changes persist on this device using local storage. There is no shared database or sign-in.</li><li><b>Illustrative:</b> performance, finance, fit scores, prospects and agent execution. No live posts or messages are sent.</li><li><b>Official public imagery:</b> artist portrait and merchandise from <a href="https://stincteamtgf.com/" target="_blank" rel="noopener noreferrer" class="green">stincteamtgf.com ↗</a>.</li><li><b>Next phase:</b> authenticated workspaces, server-side orchestration, authorized integrations and a real pilot campaign.</li></ul><div class="modal-footer">${button('Explore the demo','close',true)}</div>`);}}
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){document.getElementById('main').focus();return}page=location.hash.slice(1)||'overview';filter='All';closeModal();shell();window.scrollTo(0,0);if(pendingCampaign){let id=pendingCampaign;pendingCampaign=null;campaignDetail(id)}});
document.addEventListener('keydown',e=>{if(!document.querySelector('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...document.querySelectorAll('.modal button,.modal input,.modal textarea,.modal select,.modal a')].filter(x=>!x.disabled);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
shell();
